263→// Public API: addManyToBin
264→// ---------------------------------------------------------------------------
265→
266→/**
267→ * Add multiple deleted items to the recycle bin in a single IPNS publish.
268→ *
269→ * Unlike calling addToBin in a loop (which publishes per-item), this batches
270→ * all entries into one metadata update.
271→ */
272→export async function addManyToBin(params: {
273→  items: FolderChild[];
274→  parentIpnsName: string;
275→  parentPath: string;
276→  userPublicKey: Uint8Array;
277→  userPrivateKey: Uint8Array;
278→  folderKey?: Uint8Array;
279→}): Promise<void> {
280→  const { items, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
281→  if (items.length === 0) return;
282→
283→  const now = Date.now();
284→  const newEntries: BinEntry[] = [];
285→  for (const item of items) {
286→    const isFile = item.type === 'file';
287→    const entry: BinEntry = {
288→      id: crypto.randomUUID(),
289→      itemType: isFile ? 'file' : 'folder',
290→      name: item.name,
291→      originalParentIpnsName: parentIpnsName,
292→      originalPath: parentPath,
293→      deletedAt: now,
294→      size: 0,
295→      mimeType: '',
296→      filePointer: isFile ? (item as FilePointer) : undefined,
297→      folderEntry: !isFile ? (item as FolderEntry) : undefined,
298→    };
299→
300→    // Resolve file CID+size at soft-delete time (when folderKey is available)
301→    if (isFile && folderKey) {
302→      try {
303→        const fp = item as FilePointer;
304→        const resolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
305→        if (resolved?.cid) {
306→          const metaBytes = await fetchFromIpfs(resolved.cid);
307→          const metaJson = new TextDecoder().decode(metaBytes);
308→          const encrypted = JSON.parse(metaJson) as EncryptedFileMetadata;
309→          const fileMeta = await decryptFileMetadata(encrypted, folderKey);
310→          entry.contentCid = fileMeta.cid;
311→          entry.contentSize = fileMeta.size;
312→          if (Array.isArray(fileMeta.versions) && fileMeta.versions.length > 0) {
313→            entry.versionCids = fileMeta.versions
314→              .filter((v) => v.cid)
315→              .map((v) => ({ cid: v.cid, size: v.size ?? 0 }));
316→          }
317→        }
318→      } catch (err) {
319→        console.warn('[Bin] Failed to resolve file CID for bin entry (non-blocking):', err);
320→      }
321→    }
322→
323→    newEntries.push(entry);
324→  }
325→
326→  const store = useBinStore.getState();
327→  const currentEntries = [...store.entries, ...newEntries];
328→  const newSeq = store.sequenceNumber + 1;
329→
330→  const metadata: RecycleBinMetadata = {
331→    version: BIN_METADATA_VERSION,
332→    sequenceNumber: newSeq,
333→    entries: currentEntries,
334→  };
335→
336→  // Non-blocking: folder delete already committed, bin is best-effort
337→  try {
338→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
339→    store.setEntries(currentEntries, newSeq);
340→  } catch {
341→    console.error('[Bin] addManyToBin publish failed (non-blocking)');
342→  }
343→}
